package com.bank.addon;

import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class SubsetsDemo {

    private static final Logger log = Logger.getLogger(SubsetsDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        AddonPackager packager = new AddonPackager();

        String[] addons = {"SMS_ALERTS", "INSURANCE", "OVERDRAFT"};

        List<List<String>> packages = packager.allPackages(addons);
        log.info(() -> "Total packages: " + packages.size());   // 8 = 2^3
        packages.forEach(p -> log.info(() -> "  package: " + p));
    }
}

// ─── Would be in service/AddonPackager.java in a real project ───
class AddonPackager {

    private static final Logger log = Logger.getLogger(AddonPackager.class.getName());

    java.util.List<java.util.List<String>> allPackages(String[] addons) {
        java.util.List<java.util.List<String>> result = new java.util.ArrayList<>();
        backtrack(addons, 0, new java.util.ArrayList<>(), result);
        return result;
    }

    private void backtrack(String[] addons, int start,
                           java.util.List<String> path,
                           java.util.List<java.util.List<String>> result) {
        // Every prefix of choices is itself a valid package — record a copy.
        result.add(new java.util.ArrayList<>(path));
        for (int i = start; i < addons.length; i++) {
            path.add(addons[i]);                 // choose to include addons[i]
            backtrack(addons, i + 1, path, result);
            path.remove(path.size() - 1);        // undo — backtrack
        }
    }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("[%1$tF %1$tT] %2$-7s %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                formatMessage(record));
    }
}
